    /* ---------- Shell & navigasi ---------- */
    /* Tautan path /u/<slug> (format lama yang terlanjur tersebar) diarahkan ke
       rute hash yang benar, mempertahankan parameter tamu ?to=. */
    (function redirectPathInvitation(){
      try {
        if (location.hash) return;
        const m = location.pathname.match(/\/u\/([a-z0-9-]+)\/?$/i);
        if (m) location.replace(location.pathname.replace(/\/u\/[a-z0-9-]+\/?$/i, '/') + '#/u/' + m[1] + (location.search || ''));
      } catch(e){}
    })();
    const app = document.getElementById('app');
    let toastTimer;
    function toast(msg, err){
      const t = $('#toast'); t.textContent = msg; t.className = 'show' + (err ? ' err' : '');
      clearTimeout(toastTimer); toastTimer = setTimeout(() => t.className = '', 2800);
    }
    function go(hash){ if (location.hash === hash) render(); else location.hash = hash; }
    function shell(inner, active){
      return `
      <header class="topbar"><div class="topbar-in">
        <a class="brand" href="#/">Kita <em>Invite</em><small>Digital Invitations</small></a>
        <nav class="nav">
          <a href="#/" class="${active==='home'?'on':''}">Beranda</a>
          <a href="#/template" class="${active==='template'?'on':''}">Template</a>
          <a href="#/" data-scroll="cara-kerja">Cara Kerja</a>
          <a href="#/" data-scroll="harga">Harga</a>
          <a href="#/" data-scroll="faq">FAQ</a>
          <a href="#/dashboard" class="${active==='dashboard'?'on':''}">Dashboard</a>
          <a href="#/admin" class="${active==='admin'?'on':''}">Admin</a>
        </nav>
        <button class="burger" data-menu aria-label="Buka menu">${ICONS.menu}</button>
        <a class="btn gold sm desk" href="#/template" style="min-height:44px;padding:10px 20px">Buat Undangan</a>
      </div></header>
      <main>${inner}</main>
      <footer class="site"><div class="wrap">
        <div class="foot-grid">
          <div><a class="brand" href="#/" style="font-size:22px">Kita <em>Invite</em></a>
            <p style="margin-top:12px">Platform undangan digital & studio kreatif: temukan template premium, personalisasi dalam hitungan menit, terbitkan, dan kelola tamu Anda.</p>
            </div>
          <div><h4>Jelajahi</h4><a href="#/template">Semua Template</a><a href="#/template?kategori=pernikahan">Pernikahan</a><a href="#/template?kategori=ulang-tahun">Ulang Tahun</a><a href="#/template?kategori=korporat">Korporat</a><a href="#/demo/luxury-ivory">Demo Luxury Ivory</a></div>
          <div><h4>Produk</h4><a href="#/" data-scroll="harga">Paket & Harga</a><a href="#/" data-scroll="cara-kerja">Cara Kerja</a><a href="#/dashboard">Dashboard Pelanggan</a><a href="#/dashboard?tab=layanan">Bantuan Desain</a><a href="#/admin">Admin CMS</a></div>
          <div><h4>Bantuan</h4><a href="#/" data-scroll="faq">FAQ</a><a href="#/rencana-cloudflare">Rencana Platform Cloudflare</a><a href="#/peta-jalan">Peta Pengembangan</a></div>
        </div>
        <div class="foot-base"><span>© 2026 Kita Invite.</span><span>Prototipe interaktif · data demo fiktif</span></div>
      </div></footer>
      <nav class="bottomnav">
        <a href="#/" class="${active==='home'?'on':''}">${ICONS.home}<span>Beranda</span></a>
        <a href="#/template" class="${active==='template'?'on':''}">${ICONS.grid}<span>Template</span></a>
        <a href="#/template" class="cta">${ICONS.plus}<span>Buat</span></a>
        <a href="#/dashboard" class="${active==='dashboard'?'on':''}">${ICONS.chart}<span>Dashboard</span></a>
        <a href="#/admin" class="${active==='admin'?'on':''}">${ICONS.settings}<span>Admin</span></a>
      </nav>`;
    }

    /* ---------- Kartu template ---------- */
    function tplCard(t){
      const cat = catById(t.categoryId), sty = styleById(t.styleId);
      return `<article class="tpl-card">
        <a class="tpl-thumb" href="#/template/${t.slug}" aria-label="Lihat template ${esc(t.name)}">
          <img src="${mediaById(t.thumb).src}" alt="Contoh undangan ${esc(t.name)}" loading="lazy">
          <span class="badges">${t.featured ? '<span class="tag gold">Unggulan</span>' : ''}<span class="tag dark">${esc(t.tier)}</span></span>
          <span class="veil"><span class="s">${esc(cat.name)}</span><span class="t">${esc(t.name)}</span></span>
        </a>
        <div class="tpl-body">
          <h3>${esc(t.name)}</h3>
          <div class="meta">${esc(cat.name)} · ${esc(sty.name)}</div>
          <p>${esc(t.desc)}</p>
          <div class="tpl-foot"><div class="price">${rp(t.price)}<small>paket ${esc(t.tier)}</small></div>
          <a class="btn ghost sm" href="#/template/${t.slug}">Detail</a></div>
        </div></article>`;
    }

    /* ---------- View: Beranda ---------- */
